iterations.reply:
Two notes on the design:

- `PublishedDigest` has no field literally called "text", so the enrichment query uses `date`, percent-encoded.
- The enrichment call uses `fetch`, which returns transport failures as a value. A dead enrichment endpoint therefore can't change the output, and the result is discarded.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{published-digest, run-report};

    import aap:caps/state-rw@0.1.0;
    import aap:caps/http-client@0.1.0;

    export run: func(published: published-digest) -> run-report;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, state_rw};

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Enrichment fetch; result intentionally ignored so output is unchanged.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&published.date)
        );
        let _ = http_client::fetch(&url);

        let mut recorded: u32 = 0;
        if published.published {
            for id in &published.considered {
                state_rw::put(id, &published.date);
                recorded += 1;
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

